import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { ngrams, tokenize, vectorize } from '../src/text/tfidf.ts';
import { SKLEARN_ENGLISH_STOP_WORDS } from '../src/text/stopwords.ts';

interface Fixture {
  input: string;
  scores: Record<string, number>;
}
const fixtures: Record<string, Fixture> = JSON.parse(
  readFileSync(new URL('./fixtures.tfidf.json', import.meta.url), 'utf8'),
);

/** Reference outputs generated by the real scikit-learn vectorizer. */
const assertMatchesSklearn = (name: string, maxFeatures = 200): void => {
  const f = fixtures[name];
  assert.ok(f, `fixture ${name} present`);
  const got = vectorize(f.input, { maxFeatures });
  const want = f.scores;

  assert.deepEqual(
    [...got.keys()].sort(),
    Object.keys(want).sort(),
    `${name}: same feature set as scikit-learn`,
  );
  for (const [term, score] of Object.entries(want)) {
    assert.ok(
      Math.abs((got.get(term) ?? 0) - score) < 1e-9,
      `${name}: ${term} = ${got.get(term)}, sklearn says ${score}`,
    );
  }
};

/**
 * When a document has more candidate terms than max_features, the cut lands in
 * the middle of a run of equally-frequent terms. sklearn breaks that tie with
 * `(-tfs).argsort()`, i.e. numpy's UNSTABLE quicksort - the resulting order is
 * an artifact of introsort internals, not a rule, so it is not portably
 * reproducible and we do not try.
 *
 * It does not matter: everything at the cliff is a count-1 term scoring ~0.04,
 * far below the 0.1 significance cutoff KeywordMatcher applies. This asserts
 * the part that does matter - every term above the cutoff, which is the only
 * set that reaches the score.
 */
const CUTOFF = 0.1;
const assertSignificantTermsMatch = (name: string, maxFeatures = 200): void => {
  const f = fixtures[name];
  assert.ok(f, `fixture ${name} present`);
  const got = vectorize(f.input, { maxFeatures });

  const mine = [...got.entries()].filter(([, s]) => s > CUTOFF).sort();
  const theirs = Object.entries(f.scores)
    .filter(([, s]) => s > CUTOFF)
    .sort();

  assert.equal(got.size, Object.keys(f.scores).length, `${name}: same feature count`);
  assert.deepEqual(
    mine.map(([t]) => t),
    theirs.map(([t]) => t),
    `${name}: identical significant terms`,
  );
  for (const [term, score] of theirs) {
    assert.ok(
      Math.abs((got.get(term) ?? 0) - score) < 1e-9,
      `${name}: ${term} = ${got.get(term)}, sklearn says ${score}`,
    );
  }
};

test('tfidf: matches scikit-learn on tokenizer edge cases', () => {
  assertMatchesSklearn('tokens');
});

test('tfidf: matches scikit-learn on stop-word removal and bigram bridging', () => {
  assertMatchesSklearn('stopwords');
});

test('tfidf: matches scikit-learn on repeated terms', () => {
  assertMatchesSklearn('repeat');
});

test('tfidf: significant terms match scikit-learn on a real job description', () => {
  // Feature sets diverge only at the max_features tie cliff - see the note above.
  assertSignificantTermsMatch('real_jd');
});

test('tokenize: Node.js survives as a single token', () => {
  assert.deepEqual(tokenize('Node.js rocks'), ['Node.js', 'rocks']);
});

test('tokenize: C++ and C# collapse to "c", .NET to "net"', () => {
  assert.deepEqual(tokenize('C++ C# .NET'), ['C', 'C', 'NET']);
});

test('ngrams: stop words dropped before bigrams are formed', () => {
  assert.deepEqual(ngrams(['fox', 'and', 'the', 'lazy'], SKLEARN_ENGLISH_STOP_WORDS), [
    'fox',
    'lazy',
    'fox lazy',
  ]);
});

test('vectorize: result is L2-normalized', () => {
  const v = vectorize('python python java', { maxFeatures: 200 });
  const norm = Math.sqrt([...v.values()].reduce((a, x) => a + x * x, 0));
  assert.ok(Math.abs(norm - 1) < 1e-12);
});

test('vectorize: maxFeatures keeps the most frequent terms', () => {
  // alpha=3, then beta=2 ties with the bigram "alpha alpha"=2; ties break
  // alphabetically, so "alpha alpha" wins the second slot.
  const v = vectorize('alpha alpha alpha beta beta gamma', { maxFeatures: 2 });
  assert.deepEqual([...v.keys()], ['alpha', 'alpha alpha']);
});
